import app from 'flarum/admin/app';
import AdminPage from 'flarum/admin/components/AdminPage';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { GUEST, MEMBER, api, desk, t } from './state';
import { tagsOn } from './rows';
import GroupsTab from './GroupsTab';
import PermissionsTab from './PermissionsTab';
import MemberTab from './MemberTab';
import HistoryTab from './HistoryTab';
import { ReviewModal } from './modals';
const TABS = ['groups', 'permissions', 'member', 'history'];
// Kept for the life of the admin page, so switching tabs or pages loses nothing.
const ui = {
  groups: {
    group: 4,
    scope: 'global',
    q: '',
    by: 'area',
    compare: false,
    a: 4,
    b: MEMBER,
    onlyDiff: true,
    hint: null
  },
  permissions: {
    q: '',
    filter: 'all',
    open: null
  },
  member: {
    id: null,
    q: '',
    results: null,
    scope: 'global',
    data: null,
    loading: false
  },
  history: {
    items: null,
    hasMore: false,
    loading: false,
    version: -1,
    q: ''
  },
  presets: [],
  presetsLoaded: false
};
let tagsReady = false;

/**
 * Permission Desk: takes over the admin Permissions page. Routes: #/permissions (groups),
 * #/permissions/desk/:tab, #/permissions/desk/member/:id; core's grid at #/permissions/classic.
 */
export default class DeskPage extends AdminPage {
  oninit(vnode) {
    super.oninit(vnode);
    if (!app.store.getById('groups', '4')) ui.groups.group = GUEST;
    const memberId = Number(m.route.param('id'));
    if (memberId) ui.member.id = memberId;
    if (tagsOn() && !tagsReady) {
      app.tagList.load().then(() => {
        tagsReady = true;
        m.redraw();
      });
    }
    if (!ui.presetsLoaded) this.reloadPresets();
    window.addEventListener('beforeunload', this.beforeUnload);
  }
  onremove(vnode) {
    super.onremove(vnode);
    window.removeEventListener('beforeunload', this.beforeUnload);
  }
  beforeUnload = e => {
    if (Object.keys(desk.staged).length) {
      e.preventDefault();
      e.returnValue = '';
    }
  };
  reloadPresets = () => {
    api('GET', '/presets').then(list => {
      ui.presets = list;
      ui.presetsLoaded = true;
      m.redraw();
    });
  };
  tab() {
    if (m.route.param('id')) return 'member';
    const tab = m.route.param('tab');
    return TABS.includes(tab) ? tab : 'groups';
  }
  headerInfo() {
    return {
      className: 'PermissionDeskPage',
      icon: 'fas fa-key',
      title: t('page.title'),
      description: t('page.description')
    };
  }
  content() {
    if (tagsOn() && !tagsReady) return m(LoadingIndicator, null);
    const tab = this.tab();
    const n = desk.diff().length;
    const go = to => to === 'groups' ? '#' + app.route('permissions') : '#' + app.route('permissionDesk.tab', {
      tab: to
    });
    return m("div", {
      className: "PermissionDesk"
    }, m("div", {
      className: "PermissionDesk-top"
    }, m("nav", {
      className: "PermissionDesk-tabs",
      role: "tablist",
      "aria-label": String(t('page.title'))
    }, TABS.map(to => m("a", {
      role: "tab",
      "aria-selected": tab === to ? 'true' : 'false',
      className: 'PermissionDesk-tab' + (tab === to ? ' is-on' : ''),
      href: go(to)
    }, t('tab.' + to)))), m("a", {
      className: "Button Button--small PermissionDesk-classic",
      href: '#' + app.route('permissionDesk.classic'),
      title: String(t('classic_help'))
    }, t('classic'))), tab === 'groups' ? m(GroupsTab, {
      ui: ui.groups,
      presets: () => ui.presets,
      reloadPresets: this.reloadPresets
    }) : null, tab === 'permissions' ? m(PermissionsTab, {
      ui: ui.permissions
    }) : null, tab === 'member' ? m(MemberTab, {
      ui: ui.member
    }) : null, tab === 'history' ? m(HistoryTab, {
      ui: ui.history,
      onSaved: () => this.saved()
    }) : null, n ? m("div", {
      className: "PermissionDesk-savebar",
      role: "status"
    }, m("b", null, t('savebar.count', {
      count: n
    })), m(Button, {
      className: "Button",
      onclick: () => {
        desk.discard();
        ui.groups.hint = null;
      }
    }, t('savebar.discard')), m(Button, {
      className: "Button Button--primary",
      onclick: () => app.modal.show(ReviewModal, {
        onSaved: () => this.saved()
      })
    }, t('savebar.review'))) : null);
  }
  saved() {
    ui.groups.hint = null;
    if (ui.member.id) {
      const id = ui.member.id;
      api('GET', '/members/' + id).then(data => {
        ui.member.data = data;
        m.redraw();
      });
    }
    if (this.tab() === 'history') {
      ui.history.version = -1;
      api('GET', '/history?offset=0').then(res => {
        ui.history.items = res.changesets;
        ui.history.hasMore = res.hasMore;
        ui.history.version = desk.historyVersion;
        m.redraw();
      });
    }
  }
}